const base = String(($env && $env.N8N_BASE_URL) || 'https://n8n-production-72be.up.railway.app').replace(/\/+$/, '');
const nodo = "[MODELB] Phase-boundary Emit · notion_workspace_created";
return $input.all().map((i) => {
  const e = (i.json && i.json.error) || {};
  const msg = String(typeof e === 'string' ? e : (e.message || e.description || (Object.keys(e).length ? JSON.stringify(e) : '') || 'sin mensaje')).slice(0, 400);
  const exId = String(($execution && $execution.id) || '?');
  const wfId = String(($workflow && $workflow.id) || '?');
  console.log('[nota-perdida] ' + nodo + ' · ' + msg + ' · la corrida SIGUE · corrida ' + exId);
  return { json: {
    ok: false, code: 'nota_perdida', nota_perdida: true, nodo, error: msg,
    execution: { id: exId, url: base + '/workflow/' + wfId + '/executions/' + exId, mode: ($execution && $execution.mode) || '?', lastNodeExecuted: nodo,
      error: { message: 'SE PERDIÓ UNA NOTA · la corrida SIGUE · ' + nodo + ' · ' + msg, node: { name: nodo } } },
    workflow: { id: wfId, name: ($workflow && $workflow.name) || '?' },
  } };
});

const discovery = $('Datos del alta').item.json.discovery_result || {};
const scope = $('Datos del alta').item.json.contract_scope || [];

const activationMilestones = [];
const ttv_targets = {};

if (scope.includes('paid_ads')) {
  activationMilestones.push({ channel: 'paid_ads', milestone: 'First campaign launched', day: 14, success_metric: 'First converted lead' });
  ttv_targets.paid_ads = 14;
}
if (scope.includes('content_seo')) {
  activationMilestones.push({ channel: 'content_seo', milestone: 'Content calendar published', day: 30, success_metric: 'First organic traffic' });
  ttv_targets.content_seo = 30;
}
if (scope.includes('email')) {
  activationMilestones.push({ channel: 'email', milestone: 'Email sequence deployed', day: 7, success_metric: 'First engagement' });
  ttv_targets.email = 7;
}
if (scope.includes('industrial') || scope.includes('complex')) {
  ttv_targets.complex = 45;
}

const successPlan = {
  goals: [],
  success_metrics: [],
  timeline: activationMilestones,
  ttv_targets,
  champion_map: { identified: false, count: 0, stakeholders: [] },
  status: 'draft'
};

return [{ json: { ...successPlan, discovery_report: discovery } }];

